// Generated by scripts/stitch-to-react.mjs from Stitch screen "Dev in_ 아이디 찾기" (a325a7b416484edfacf35d8f124d2277).
// 모양은 비밀번호 찾기 화면과 같은 공통 조각(components/findAccount)으로 맞춘다.
import { useState, type FormEvent } from "react";
import { Link } from "react-router-dom";
import { findLoginId, type FindLoginIdResult } from "../api/auth";
import { getErrorMessage } from "../api/client";
import { INPUT_PATTERNS, INPUT_RULES, formatPhoneInput, toPhoneDigits } from "../api/member";
import "./FindId.css";
import AccountLinks from "../components/AccountLinks";
import AuthHeader from "../components/AuthHeader";
import Footer from "../components/Footer";
import { HEADER_BUTTON_CLASS, HEADER_BUTTON_COLOR } from "../components/headerStyles";
import {
  FieldHint,
  FieldLabel,
  FindCard,
  FindCardFooter,
  FindCardHeader,
  FindPageHeading,
  NoticeBox,
  StatusMessage,
} from "../components/findAccount/FindAccountParts";
import {
  INPUT_CLASS,
  PRIMARY_BUTTON,
  PRIMARY_BUTTON_DISABLED,
  SECONDARY_BUTTON,
} from "../components/findAccount/findAccountStyles";

type Result =
  { status: "empty" } | { status: "found"; data: FindLoginIdResult } | { status: "failed"; message: string };

const RESULT_TITLE = "조회된 아이디 정보";

function formatDate(value: string) {
  const date = new Date(value);
  const pad = (n: number) => String(n).padStart(2, "0");
  return `${date.getFullYear()}.${pad(date.getMonth() + 1)}.${pad(date.getDate())}`;
}

export default function FindId() {
  const [nickname, setNickname] = useState("");
  const [phone, setPhone] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [result, setResult] = useState<Result>({ status: "empty" });

  const nicknameValid = INPUT_PATTERNS.nickname.test(nickname);
  const phoneValid = INPUT_PATTERNS.phone.test(toPhoneDigits(phone));
  const canSubmit = nicknameValid && phoneValid && !submitting;

  async function handleSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (!canSubmit) return;
    setSubmitting(true);
    try {
      const data = await findLoginId(nickname, toPhoneDigits(phone));
      setResult({ status: "found", data });
    } catch (err) {
      setResult({ status: "failed", message: getErrorMessage(err) });
    } finally {
      setSubmitting(false);
    }
  }

  const nicknameInvalid = nickname !== "" && !nicknameValid;
  const phoneInvalid = phone !== "" && !phoneValid;

  return (
    <div id="page-find-id">
      <div
        className="min-h-screen flex flex-col justify-between text-black antialiased selection:bg-[#FFD43B]"
        style={{
          backgroundColor: "rgb(255, 253, 245)",
          backgroundImage: "radial-gradient(rgb(217, 212, 195) 1.2px, transparent 1.2px)",
          backgroundSize: "18px 18px",
        }}
      >
        <AuthHeader>
          <Link className={`${HEADER_BUTTON_CLASS} ${HEADER_BUTTON_COLOR.white}`} to="/login">
            로그인
          </Link>
          <Link className={`${HEADER_BUTTON_CLASS} ${HEADER_BUTTON_COLOR.yellow}`} to="/signup">
            회원가입
          </Link>
        </AuthHeader>

        <main className="flex-1 max-w-5xl w-full mx-auto px-4 py-10 flex flex-col justify-center">
          <FindPageHeading
            description="가입 시 등록한 닉네임과 전화번호로 본인 확인 후 아이디를 확인하실 수 있습니다."
            title="아이디 찾기"
          />

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 items-stretch">
            {/* LEFT CARD: 회원 정보 입력 */}
            <FindCard className="justify-between">
              <div>
                <FindCardHeader badge="전화번호 본인 확인" title="회원 정보 입력" tone="white" />

                <form className="space-y-5" noValidate onSubmit={handleSubmit}>
                  <div>
                    <FieldLabel htmlFor="user-name">닉네임</FieldLabel>
                    <input
                      autoComplete="nickname"
                      className={INPUT_CLASS}
                      id="user-name"
                      maxLength={10}
                      onChange={(e) => setNickname(e.target.value)}
                      placeholder="닉네임 입력"
                      type="text"
                      value={nickname}
                    />
                    <FieldHint tone={nicknameInvalid ? "error" : "idle"}>
                      {nicknameInvalid ? INPUT_RULES.nickname : "가입할 때 등록한 닉네임"}
                    </FieldHint>
                  </div>
                  <div>
                    <FieldLabel htmlFor="user-phone">전화번호</FieldLabel>
                    <input
                      autoComplete="tel"
                      className={`${INPUT_CLASS} tracking-wider`}
                      id="user-phone"
                      inputMode="numeric"
                      maxLength={13}
                      onChange={(e) => setPhone(formatPhoneInput(e.target.value))}
                      placeholder="010-0000-0000"
                      type="tel"
                      value={phone}
                    />
                    <FieldHint tone={phoneInvalid ? "error" : "idle"}>
                      {phoneInvalid
                        ? "01로 시작하는 10~11자리 숫자를 입력해 주세요"
                        : "숫자만 입력하면 하이픈이 자동으로 들어가요"}
                    </FieldHint>
                  </div>

                  <NoticeBox>보안을 위해 아이디는 앞 3자리만 보여드리고 나머지는 * 로 가려요.</NoticeBox>

                  <div className="pt-2">
                    <button
                      className={canSubmit ? PRIMARY_BUTTON : PRIMARY_BUTTON_DISABLED}
                      disabled={!canSubmit}
                      type="submit"
                    >
                      {submitting ? "찾는 중..." : "아이디 찾기"}
                    </button>
                  </div>
                </form>
              </div>

              <FindCardFooter>
                <AccountLinks current="find-id" />
              </FindCardFooter>
            </FindCard>

            {/* RIGHT CARD: 조회 결과 (조회 전 / 찾음 / 일치하는 회원 없음) */}
            <FindCard className="min-h-[360px]">
              <div aria-live="polite" className="flex-1 flex flex-col">
                {result.status === "empty" && (
                  <>
                    <FindCardHeader badge="WAITING" title={RESULT_TITLE} tone="gray" />
                    <StatusMessage icon="🔍" title="아직 조회한 정보가 없어요">
                      왼쪽에 닉네임과 전화번호를 입력하고
                      <br />
                      [아이디 찾기]를 누르면 여기에 표시돼요.
                    </StatusMessage>
                  </>
                )}

                {result.status === "found" && (
                  <>
                    <FindCardHeader badge="MATCHED" title={RESULT_TITLE} tone="green" />
                    <div className="mb-5 space-y-1">
                      <p className="text-sm font-bold text-black">
                        <span className="bg-[#FFD43B] px-1.5 py-0.5 border-[1.5px] border-black rounded">
                          {result.data.nickname}
                        </span>
                        {" 회원님의 아이디는 다음과 같습니다."}
                      </p>
                      <p className="text-[13px] text-gray-600 font-medium">
                        계정 보안을 위해 아이디 일부가 가려져 있습니다.
                      </p>
                    </div>
                    <div className="bg-[#F9F7F1] border-[2px] border-black rounded-xl p-4 mb-6">
                      <div className="flex items-center justify-between mb-3">
                        <span className="text-[11px] font-mono font-bold tracking-wider text-[#2563EB]">
                          DEVELOPER ID
                        </span>
                        <span className="text-[11px] font-mono font-semibold text-gray-600">
                          가입일 : {formatDate(result.data.createdAt)}
                        </span>
                      </div>
                      <div className="bg-white border-[2px] border-black rounded-lg px-4 py-3">
                        <span className="text-lg font-mono font-extrabold tracking-widest text-black">
                          {result.data.maskedLoginId}
                        </span>
                      </div>
                    </div>
                    <div className="space-y-3 mt-auto">
                      <Link className={PRIMARY_BUTTON} to="/login">
                        로그인하러 가기 →
                      </Link>
                      <Link className={SECONDARY_BUTTON} to="/find-password">
                        비밀번호 찾기
                      </Link>
                    </div>
                  </>
                )}

                {result.status === "failed" && (
                  <>
                    <FindCardHeader badge="NOT FOUND" title={RESULT_TITLE} tone="red" />
                    <StatusMessage icon="❗" iconClass="bg-[#FFD43B]" title={result.message}>
                      닉네임과 전화번호를 다시 확인해 주세요.
                      <br />
                      가입한 적이 없다면 회원가입을 해 주세요.
                    </StatusMessage>
                    <Link className={`${SECONDARY_BUTTON} mt-auto`} to="/signup">
                      회원가입 하러 가기
                    </Link>
                  </>
                )}
              </div>
            </FindCard>
          </div>
        </main>

        <Footer />
      </div>
    </div>
  );
}
